{
    "API_calls": [],
    "collected_information": {
        "environment_setup": {
            "python_versions_supported": "Python >= 3.9 and < 3.14",
            "installation_methods": {
                "pip": "pip install dowhy",
                "poetry": "poetry add dowhy",
                "conda": "conda install -c conda-forge dowhy",
                "development_version": "pip install git+https://github.com/py-why/dowhy@main"
            },
            "optional_dependencies": {
                "graph_input": "pip install pydot",
                "enhanced_visuals": [
                    "sudo apt install graphviz libgraphviz-dev graphviz-dev pkg-config",
                    "pip install --global-option=build_ext --global-option=\"-I/usr/local/include/graphviz/\" --global-option=\"-L/usr/local/lib/graphviz\" pygraphviz"
                ]
            },
            "dependencies": {
                "base": [
                    "cython >=3.0",
                    "scipy",
                    "numpy",
                    "pandas",
                    "statsmodels",
                    "sympy",
                    "scikit-learn",
                    "networkx"
                ],
                "optional_visualization": ["pydot ^1.4.2", "pygraphviz >=1.9", "matplotlib >=3.5.3"],
                "development": [
                    "poethepoet",
                    "flask",
                    "black",
                    "pytest",
                    "pytest-cov",
                    "pytest-split",
                    "jupyter",
                    "flaky",
                    "keras",
                    "xgboost",
                    "torch",
                    "pytorch-lightning",
                    "mypy"
                ],
                "documentation": [
                    "sphinx",
                    "seaborn",
                    "cdt",
                    "nbconvert",
                    "nbsphinx",
                    "IPython"
                ]
            },
            "environment_setup_commands": {
                "poetry": {
                    "base": "poetry install",
                    "with_extras": "poetry install -E plotting -E pydot -E pygraphviz -E econml --with docs"
                }
            }
        },
        "testing": {
            "ci_testing_commands": {
                "regular_tests": "poetry run poe test --splits 6 --group ${{ matrix.test-group }}",
                "econml_tests": "poetry run poe test_econml",
                "readme_format_check": [
                    "pip install poetry-dynamic-versioning",
                    "pip install twine",
                    "poetry-dynamic-versioning",
                    "poetry build",
                    "twine check dist/*"
                ]
            },
            "nightly_testing_commands": {
                "advanced_testing": "poetry run poe test_advanced",
                "environment_prerequisites": {
                    "os": "Ubuntu (GitHub Actions runner)",
                    "python_versions": ["3.9", "3.10", "3.11", "3.12", "3.13"],
                    "poetry_version": "2.1.3",
                    "llvm_required_packages": ["graphviz", "libgraphviz-dev", "graphviz-dev", "pkg-config"],
                    "additional_commands": [
                        "python -m pip install --upgrade pip",
                        "poetry install -E plotting -E pydot -E pygraphviz -E econml --with docs"
                    ]
                }
            }
        }
    },
    "terminate": true
}
